INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101063, 3, 'for', '82a6da1e-3b5b-55d8-92e8-3daf4bf4e90a', 'Maine and Vermont let people vote from prison, and neither state has suffered an election-integrity meltdown. That matters because the strongest argument against restoration is usually a vague fear that voting somehow cheapens punishment, yet the two states that go furthest have the least drama. The [European Court of Human Rights ruled in 2005](https://www.echr.coe.int/) that blanket bans on prisoner voting violate basic rights, and most European democracies allow it with no visible harm to public safety or the seriousness of sentences. We already count incarcerated people in the census for purposes of political representation, so we are happy to use their bodies for apportionment while denying them a voice. Drawing the line at the ballot box is a choice, not a necessity, and the evidence from the states and countries that chose differently is reassuringly boring.', 24, '2026-09-23 18:55:01+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101064, 3, 'against', '648235a5-4b71-5a93-af6b-338753de5433', 'My shop was robbed twice in three years, and the second time the man who did it had a record that filled a folder. I am not heartless, but I watched the court order restitution my insurance never fully covered, and I think finishing a sentence means finishing all of it. Florida''s Amendment 4 kept that distinction: it excluded murder and felony sexual offenses, and lawmakers later required fines, fees, and restitution to be paid first, because a sentence is not just time served. [The Brennan Center](https://www.brennancenter.org/) notes that hundreds of thousands of Floridians still owe legal financial obligations, and calling those debts a poll tax dodges the fact that victims were ordered that money by a judge. Automatic restoration sounds compassionate until you are the person still waiting on the check the court said you were owed.', 6, '2026-09-24 03:23:03+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101065, 3, 'against', '0d896c16-a13c-5c1e-901c-fa4d619b28d1', 'The Constitution leaves voter qualifications mostly to the states, and that is not a loophole, it is the design. People in different states genuinely disagree about what completing a sentence requires, and a one-size rule from Washington would erase that debate instead of settling it. When Florida voters passed Amendment 4 and when Virginia''s governors issued restoration orders, those were state decisions reflecting state values, which is how a federal system is supposed to work. [Pew Research](https://www.pewresearch.org/short-reads/2018/11/15/how-americans-view-some-of-the-voting-policies-approved-at-the-ballot-box/) has found broad but not universal support for restoration, with real disagreement about violent offenses and timing. Automatic nationwide restoration trades that democratic argument for a mandate, and on questions this contested, the argument is the point.', 5, '2026-09-23 16:17:38+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101066, 3, 'against', 'ab79c15a-2a12-5870-a17c-810d6b1a9fcd', 'Everyone talks about second chances, but almost nobody mentions how fast the second chance gets wasted. The [Bureau of Justice Statistics](https://bjs.ojp.gov/) found that 83% of state prisoners released were rearrested within nine years, which means a huge share of people restored on day one will be back inside before the next presidential election. I am not saying nobody deserves the vote, I am saying timing matters: a waiting period or a clean-record stretch proves the reintegration is real instead of assumed. States that restore rights after parole or probation ends already strike this balance, and their approach respects both the person who stayed straight and the community taking the risk. Automatic restoration at the prison door skips the only evidence that matters, which is what someone does with their freedom.', 15, '2026-09-24 00:39:19+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101067, 4, 'for', 'aa41ea2e-1856-5bfc-9547-d56c2937181a', 'My students learn that everyone pays taxes, and then I read the [ProPublica investigation](https://www.propublica.org/article/the-secret-irs-files-trove-of-never-before-seen-records-reveal-how-the-wealthiest-avoid-income-tax) showing the 25 richest Americans paid an effective federal income tax rate of just 3.4% from 2014 to 2018. The trick is simple: never sell. Borrow against your stock, live off the loans, and let the gains compound untaxed until death wipes the slate through stepped-up basis. The White House proposal answers this directly: a 25% minimum tax on households worth more than $100 million, covering unrealized gains, hitting roughly the top 0.01% and raising an estimated $360 billion over a decade. That is not a tax on teachers with a 401(k). It is a tax on a loophole you need nine figures to use.', 26, '2026-09-23 20:39:08+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101068, 4, 'for', '2d536008-cfe6-5e5d-8112-4b1394eb3f5a', 'I pay taxes on every dollar I earn before I ever see it, and I am tired of being told the system cannot ask the same of people with more money than a hospital. Economists Emmanuel Saez and Gabriel Zucman found that in 2018 [the 400 richest families paid a lower total effective tax rate](https://www.nytimes.com/2019/10/06/opinion/income-tax-rate-wealthy.html) than the bottom half of earners, which flips the whole idea of progressive taxation upside down. Unrealized gains are real economic power: they buy yachts through loans, they buy companies, they buy elections, and the tax code pretends they do not exist until a sale the owner can delay forever. A minimum tax on the wealthiest households would not fix every inequity, but it would end the absurdity of a nurse paying a higher rate than a billionaire. If the code can track my overtime down to the penny, it can value a stock portfolio.', 5, '2026-09-23 20:30:47+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101069, 4, 'for', 'e221802f-5357-518d-9f63-27b1c106c174', 'The unworkable objection ignores how much mark-to-market taxation already exists. Futures traders have their contracts marked to market every year under [Section 1256 of the tax code](https://www.congress.gov/), and nobody calls that the end of commodities markets. The Netherlands taxes an assumed return on savings and investments instead of waiting for a sale, and Americans who renounce citizenship already pay an exit tax on unrealized gains. For households over $100 million, portfolios are mostly publicly traded securities with a price anyone can look up in seconds, so the valuation horror stories about family farms are aimed at the wrong target. We built the plumbing for this decades ago. What is missing is the political will to turn it on for the people who benefit most from it being off.', 9, '2026-09-23 22:09:47+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101070, 4, 'against', '0eef4bb1-4054-5855-a228-89a413d85030', 'I built my company over 22 years, and on paper it is worth enough that a tax like this would notice me if the threshold ever drifts down, which thresholds always do. For founders, most wealth is shares you cannot sell without losing control of the company your employees depend on, so a tax on unrealized gains means selling pieces of the business every year just to pay the IRS. Startup employees get hit too: engineers holding illiquid options would owe real cash on paper value they cannot touch, forcing them to walk away from the equity they earned. The [Tax Policy Center](https://www.taxpolicycenter.org/) has warned about exactly these liquidity crunches, and they are not theoretical, they are arithmetic. A tax bill should not force a founder to choose between paying Washington and keeping her company.', 25, '2026-09-23 21:21:56+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101071, 4, 'against', '7d76392f-0482-5082-ad2f-2b4b16a71d47', 'I have watched every tax-only-the-rich promise of my lifetime eventually knock on the middle class door, and this one has the same knock built in. The 16th Amendment allows taxes on income, and the Supreme Court in [Moore v. United States (2024)](https://www.supremecourt.gov/) upheld a tax on already-realized foreign earnings while pointedly leaving the bigger question undecided, which means a tax on gains nobody has received is on shaky constitutional ground. Even if it survives for billionaires today, the machinery it builds, annual federal valuation of everything you own, is ready-made for the next revenue hunt. My 401(k) holds unrealized gains too, and I am not comforted by promises that the line will never move. Lines drawn for revenue always move.', 8, '2026-09-23 13:49:45+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101072, 4, 'against', '9634b19f-6504-5eb4-9501-9508b05f23ed', 'My parents own a small apartment building, and I have watched them argue with the county every year about what it is worth, because appraisals are opinions with letterhead. Now imagine the IRS doing that annually for every private business, art collection, and family farm in the country, with penalties if their opinion differs from yours. France tried a wealth tax and [repealed it in 2018](https://www.reuters.com/) after economists tied it to capital flight, and several other European countries walked away from similar experiments for the same reason. Valuation disputes would flood the courts, compliance costs would crush exactly the mid-sized businesses the threshold supposedly spares, and the revenue projections would melt on contact with reality. A tax the government cannot measure fairly is a tax it cannot levy fairly.', 12, '2026-09-23 16:14:18+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101073, 23, 'for', '8e1ee936-3d62-57ca-973c-8572c907b23d', 'Every new filmmaking tool gets this funeral. When digital cameras arrived, purists said film was dead; when CGI arrived, they said acting was over, and then performances like Andy Serkis as Gollum got studied in acting classes. The Academy''s 2025 rule gets the principle right: generative AI [neither helps nor harms](https://www.oscars.org/news) a film''s eligibility, because voters are asked to judge the human authorship at the heart of the work. A director who uses AI to pre-visualize a sequence still makes a thousand creative decisions, just as a cinematographer using a digital camera does. Banning AI films from awards would not protect artistry, it would just freeze the definition of artistry at whatever tools existed in 2022.', 9, '2026-09-24 10:38:17+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101074, 23, 'for', '01016111-7c7d-5978-845d-676b6ce468a7', 'I am in film school with $40,000 in debt and a laptop, and tools like [Runway](https://runwayml.com/) and OpenAI''s Sora are the first thing that has ever made me feel like I could compete with a studio. A period street scene that would cost a major production hundreds of thousands can now be prototyped by a kid in a dorm room, which means the next great director might not need a trust fund or a studio deal. Awards eligibility matters here because recognition is the currency that turns an unknown into a working filmmaker: festivals and prizes are how outsiders get meetings. If the Oscars wall off AI-assisted work, they are not defending craft, they are defending the budgets that already win everything. Let the kid with the laptop enter the race.', 18, '2026-09-24 12:59:00+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101075, 23, 'for', 'd193d39a-90f5-5315-8985-4ddd7f60f9b2', 'The Academy already solved the transparency problem, and everyone is ignoring the solution. Its rules now require filmmakers to [disclose AI use](https://www.oscars.org/news), so voters know what they are judging, the same way credits have always told us who did what. With that disclosure in place, the craft categories could become the most exciting part of the night: imagine production designers and visual effects artists competing on how inventively they wield these tools instead of pretending the tools do not exist. Cinematography awards did not die when color film arrived, they got more interesting. Eligibility with disclosure keeps the focus where it belongs, on what the humans chose to make, while dragging the conversation about AI in film into the open where it can actually be judged.', 9, '2026-09-24 12:07:51+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101076, 23, 'against', '6069f4d9-134d-5568-b84d-113b4781f21f', 'I spent two summers as a background actor, and I watched real people lose real weeks of work when productions started fixing crowds in post with digital extras. The 2023 strikes were not abstract: [SAG-AFTRA walked out for 118 days](https://www.sagaftra.org/) and writers for 148, largely over AI replacing human labor, and thousands of working actors still have not recovered. Awards are the industry''s loudest statement about what it values, and handing its top honors to films built on the technology that picket lines were drawn against would be a betrayal with a trophy attached. Nobody is saying AI users are villains, but the Oscars should celebrate the human performances, writing, and craft that audiences actually connect with. Some lines are worth drawing, and this is the cheapest one.', 22, '2026-09-24 11:52:40+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101077, 23, 'against', '82d8950f-6db7-53cc-b1e2-7d3334c7b651', 'My illustrations have been scraped into training sets I never agreed to, and now I am supposed to applaud when that same pipeline wins Best Picture. Generative models learned their craft from millions of uncompensated artists, writers, and actors, and the [lawsuits over that training data](https://www.reuters.com/technology/artificial-intelligence/) are still working through the courts. Giving AI-generated films the industry''s highest honor would reward the appropriation before the law has even decided whether it was theft. I am not a purist about tools: I use digital brushes every day. But there is a difference between a tool and a machine built on other people''s work without permission or pay. Until the people whose art trained these models are compensated, awards should go to films made by people, not composites of them.', 10, '2026-09-24 13:07:36+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101078, 23, 'against', '1353e9e6-bed7-5215-8608-5bbd274806bb', 'Awards are supposed to be a fair fight, and AI makes the fight about computing budgets instead of imagination. A major studio can train proprietary models on its own century of footage, hire teams of AI specialists, and generate thousands of variations of every scene, while an independent filmmaker gets whatever the public tools spit out. We have seen this movie before: every democratizing technology in Hollywood, from CGI to streaming, ended up consolidating power in the studios that could afford to do it best. The [2023 strikes](https://apnews.com/hub/entertainment) happened because workers saw this consolidation coming. Keeping AI-generated films out of major awards would not stop the technology, but it would keep the industry''s highest honors measuring human creativity rather than corporate compute.', 7, '2026-09-24 12:43:13+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101079, 24, 'for', '51ef71d8-14d6-5375-9c49-b8052358cdbb', 'I have taught for 14 years, and the phone is the single biggest change in my classroom, bigger than any curriculum rewrite. [UNESCO''s 2023 Global Education Monitoring Report](https://www.unesco.org/gem-report/en) found it can take students up to 20 minutes to refocus after a single notification, which means one buzz can erase a third of a class period. Florida''s 2023 law banning phones during instructional time was not some authoritarian whim, it was a response to teachers begging for backup. My students are good kids, and they still cannot resist a screen engineered by thousand-person teams to be irresistible. A nationwide ban would do what I cannot do alone: make the classroom a place where attention is the default instead of the exception.', 25, '2026-09-24 11:48:11+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101080, 24, 'for', '9d8ffff2-6857-5147-8090-f340fa759a75', 'I hand out ice packs and bandages, but most of what walks into my office now is anxiety, and the phone is almost always in the story. The [CDC''s 2021 Youth Risk Behavior Survey](https://www.cdc.gov/yrbs/) found 57% of teen girls felt persistently sad or hopeless, and bullying, much of it starting or spreading on phones during the school day, is a documented driver. [Common Sense Media](https://www.commonsensemedia.org/) found teens receive a median of 237 notifications a day, a huge share of them during school hours, which is not communication, it is harassment by volume. A school cannot fix a teenager''s whole digital life, but it can give them seven hours where the pile-on pauses. I have watched kids exhale when the phone goes in the pouch. That exhale is the policy working.', 24, '2026-09-24 12:54:24+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101081, 24, 'for', 'c4599b0a-6dbb-5079-b6bf-445005adc8f6', 'Every objection to a ban melts when you look at how schools actually do it. Lockable pouches from companies like [Yondr](https://www.overyondr.com/) cost a few dollars per student, kids keep the phone on their person, and the school office handles genuine emergencies, which is what offices did for decades before every child had a phone. My daughter''s school adopted pouches last year and the change was immediate: lunch got louder, teachers stopped playing phone police, and the emergency calls turned out to be mostly forgotten homework and ride logistics. Parents survived not texting their kids for six hours in 1995, and the office phone still works. This is a solved problem pretending to be a hard one.', 12, '2026-09-24 13:28:27+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101082, 24, 'against', '5293caab-5d08-5c31-9778-fd2be406b076', 'I am a mother of two, and I will not apologize for wanting to reach my children during the school day. School shootings and lockdowns are not hypotheticals, they are drills my kids do monthly, and in a real emergency the office line jams while a text gets through. [Pew Research](https://www.pewresearch.org/internet/2025/10/08/how-parents-describe-their-kids-tech-use/) has found most parents of teens count the phone''s safety benefits as a major reason their child has one, and that instinct does not vanish at the classroom door. A ban also assumes every family has the same safety net, but my neighbor''s daughter walks home alone past a busy intersection and texts when she arrives. Schools can restrict use without confiscating the lifeline. My child''s safety is not a distraction to be managed.', 26, '2026-09-24 11:32:04+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101083, 24, 'against', 'f80c2d72-01bd-55cd-8684-090bd4e11464', 'I am a junior, and the adults debating this clearly have not watched a ban fail in real time. My school tried one: teachers spent the first ten minutes of every period collecting phones instead of teaching, and the kids who wanted to cheat just brought a second phone. Meanwhile I use my phone for things the school cannot replace: a translation app for my mom at parent-teacher night, photos of the whiteboard because I process better visually, and the bus tracker that tells me if I missed my ride home. [Pew](https://www.pewresearch.org/internet/2023/12/11/teens-social-media-and-technology-2023/) reports nearly all teens have phone access, but access is not equal, and for some of us the phone is the only computer we own. Punish the misuse, sure. But a blanket ban treats every student like the worst one in the room.', 17, '2026-09-24 10:28:18+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101084, 24, 'against', 'be9eb174-d4ab-5567-9a25-176d6f53c416', 'A ban treats the symptom and declares victory while the disease clocks out at 3 p.m. The anxiety, the comparison, the doomscrolling, all of it resumes the second the pouch opens, because we have taught kids nothing about managing the device, only that adults can take it away. [UNESCO](https://www.unesco.org/) itself paired its call for restrictions with a demand for better digital literacy, and the second half is the part schools keep skipping. I work in tech, and I can tell you these products are designed to capture attention; willpower lectures delivered to a banned phone do not build resistance, practice does. Teach students to notice manipulation, to set their own limits, to sit with boredom, and you have given them something that works after graduation. A ban just schedules the problem for later.', 8, '2026-09-24 10:30:40+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101085, 8, 'for', '391df4bf-3997-5a4b-b74e-67f89cc9c301', 'The numbers make the abstract concrete. The 2017 Equifax breach exposed the personal data of [147 million Americans](https://www.ftc.gov/news-events/news/press-releases/2019/07/equifax-pay-575-million-part-settlement-ftc-cfpb-states-alleged-failure-take), followed by a $575 million FTC settlement, and the executives who oversaw the security failures kept their pay while shareholders and consumers absorbed the cost. [Section 304 of Sarbanes-Oxley](https://www.congress.gov/) already claws back CEO and CFO compensation after accounting restatements, because Congress decided some failures are personal, and privacy failures at this scale deserve the same logic. A company fine is a line item; a clawback is a career event. Boards will fund security properly when the people signing the risk memos know their own compensation is on the line, not just the company''s.', 15, '2026-09-23 12:12:37+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101086, 8, 'against', 'fb8d24b5-9542-55f8-83a0-53212a53836f', 'Here is the perverse outcome nobody mentions: personal liability will make breach disclosure slower, not faster. If a director faces personal ruin for a repeat incident, the rational move is to litigate the definition of violation, delay the announcement, and lawyer every forensic report, which is the opposite of what victims need. It will also shrink the talent pool: qualified independent directors will avoid the boards of data-heavy companies, leaving those boards to insiders with less appetite for hard questions. The [SEC''s own cyber disclosure rules](https://www.sec.gov/) already push companies toward faster reporting, and personal liability pulls the other way. We want directors who ask uncomfortable questions early. Threatening their homes and savings gets us directors who ask nothing, on the record, ever.', 7, '2026-09-23 18:19:24+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101087, 9, 'for', 'f1d74300-6314-519d-858e-21531de9e328', 'Follow the money and the no-audience excuse collapses. [Deloitte projected](https://www2.deloitte.com/) women''s elite sports would surpass $1 billion in annual revenue, and the 2024 NCAA women''s championship averaged [18.7 million viewers](https://www.espn.com/), outdrawing the men''s final that year. The WNBA just posted its most-watched regular season in 24 years. Audiences this size do not appear by magic; they are built by the highlight shows, front pages, and lead segments that tell casual fans something matters. Every milestone buried on page six is a commercial opportunity the outlet then cites as proof nobody cares. Prominent coverage is not charity for women''s sports. It is the marketing engine the men''s game has enjoyed for a century, finally pointed in both directions.', 17, '2026-09-23 17:51:27+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101088, 9, 'against', '486b6fdb-fea2-5050-bdda-391e1e4b1031', 'A mandated lead segment is the fastest way to make coverage feel like homework. Young fans, the exact audience women''s sports needs, do not watch 11 p.m. highlight shows; they live on TikTok, YouTube, and streaming, where the [WNBA and NWSL are already thriving](https://www.sportsbusinessjournal.com/) without any parity rule. Forcing legacy outlets to match men''s placement risks tokenism: a perfunctory 30 seconds at the top of the broadcast that satisfies a quota while the real storytelling stays with the men''s leagues. Editorial judgment exists because newsworthiness is real, and audiences smell condescension instantly. The better demand is better coverage everywhere fans actually are, not equal minutes on a format that is aging out.', 20, '2026-09-23 21:47:39+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101089, 10, 'for', '36cfff0c-65b8-5120-a6ca-5a6638482165', 'The Academy keeps embarrassing its own majority. Below-the-line craftspeople, editors, sound mixers, costume designers, make up the bulk of Academy membership, yet the telecast treats their awards as bathroom breaks. That is not just rude, it is bad business: international audiences tune in for their countries'' craft nominees, the way India showed up in force when RRR''s Naatu Naatu won, and those viewers do not care which category airs at 11 p.m. The [2022 pre-taped categories experiment](https://www.thewrap.com/iatse-president-oscars-categories-pretaped/) drew open fury from the guilds whose dues fund the institution. A show that honors film should not rank filmmakers by fame. Give every category its live moment, and trim the montages and musical numbers nobody asked for.', 9, '2026-09-24 02:46:58+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101090, 10, 'against', 'a84309e6-d148-54ef-8191-634b14c46c3f', 'The Oscars are a television show before they are a ceremony, and the economics are brutal. Viewership fell from [43.7 million in 2014](https://www.nielsen.com/) to about 19.5 million in 2024, and the broadcast rights and ad dollars that fund the Academy depend on stopping that slide. Producers are not villains for protecting the categories casual viewers tune in for; they are trying to keep the lights on so there is a show at all. But equal live minutes is a false choice. Put the craft categories in dedicated streaming segments with full, unbleeped speeches and real production value, and you might actually serve those artists better than a rushed 90 seconds at 11:40 p.m. Tradition says everything must be live. The audience has already moved on from that tradition.', 23, '2026-09-24 02:05:47+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101121, 5, 'for', '0f1121a7-8c4b-5bc6-a6ae-cbe94e4ea1a6', 'One lit phone in a dark theater ruins the movie for two hundred people. That is not a personal choice, it is a shared-space problem, exactly like talking during the film. Alamo Drafthouse proved the market rewards strictness: their famous no-talking, no-texting rule, enforced with ejection, is the core of their brand, and plenty of customers choose them partly because of it ([policy](https://drafthouse.com)). Making phone-free the default, with a few clearly labeled phone-friendly screenings for anyone who needs a device, protects the experience for the majority without banning anyone. Theaters sell immersion you cannot get on a couch. If they will not defend it, streaming will keep winning.', 9, '2026-09-23 19:31:16+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101122, 5, 'for', 'ace1be90-d574-5cee-8335-0f95f8b90978', 'I worked concessions all through college, and the number one complaint at the podium was never ticket prices. It was the glow from someone''s screen three rows down. Locking pouches already work at scale: comedians like Dave Chappelle and musicians like Jack White have toured with [Yondr pouches](https://www.overyondr.com/), and audiences adapted within a single show. The pouch takes ten seconds at the door and unlocks at stations on the way out, so nobody is truly unreachable in a real emergency. If comedy clubs running two-drink minimums can pull this off night after night, a multiplex can manage it for matinees.', 12, '2026-09-24 00:52:16+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
